"""Drafts describe actual flows; configuring an operator changes the version."""
import hashlib
import json
import re

from fastapi import HTTPException
from app.core.config import Settings

TEMPLATE_VERSION = '2026-10-07.1'


def document_config(settings: Settings) -> dict:
    operator = {
        'name': settings.privacy_operator_name or '[Имя владельца / наименование ИП или ТОО]',
        'identifier': settings.privacy_operator_id or '[БИН / ИИН владельца]',
        'email': settings.privacy_contact_email or '[Email для обращений по персональным данным]',
    }
    ready = bool(settings.privacy_operator_name and re.fullmatch(r'\d{12}', settings.privacy_operator_id)
                 and re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', settings.privacy_contact_email)
                 and settings.privacy_storage_country == 'KZ' and settings.privacy_documents_approved)
    sections = [
        {'title': 'Кто обрабатывает данные', 'text': f"Владелец и оператор: {operator['name']}. БИН / ИИН: {operator['identifier']}. Контакт: {operator['email']}."},
        {'title': 'Аккаунт, покупки и безопасность', 'text': 'Обрабатываем ФИО, имя в профиле, email, хеш пароля, данные браузерной сессии, корзину, избранное и заказы. Для доставки вы добавляете телефон, адрес и при необходимости координаты. Цели: вход в аккаунт, сохранение выбранных товаров, оформление и исполнение заказов, поддержка и защита магазина.'},
        {'title': 'Срок и хранение', 'text': 'Данные аккаунта нужны, пока вы пользуетесь аккаунтом; сведения по заказам — пока нужны для исполнения обязательств и сроков хранения, установленных законом. Записи согласия подтверждают ваш выбор. Перед реальным запуском владелец утверждает конкретный график хранения, удаления и резервных копий. Базы персональных данных должны находиться в Казахстане; страну размещения и резервного хранения проверяет владелец.'},
        {'title': 'Передача данных и карта', 'text': 'Согласие на аккаунт не разрешает произвольную передачу данных третьим лицам. При поиске адреса Geoapify получает введённый основной адрес или координаты. Имя, телефон, квартира и комментарий заказа в этот запрос не входят. Карта использует OpenStreetMap, поиск ветклиник — Overpass; браузер обращается к серверу карты и передаёт сетевые данные. Эти сервисы могут обрабатывать запросы за пределами Казахстана. Перед запуском владелец уточняет получателей, страны, основания и отдельное согласие для таких передач.'},
        {'title': 'Отзывы и фотографии', 'text': 'Отзыв, ответы, имя автора и прикреплённые фото после публикации видны всем посетителям. Согласие на аккаунт и согласие на аналитику не включают разрешение на публикацию. Не прикрепляйте чужие персональные данные или фотографии людей без разрешения. Перед реальным запуском владелец оформляет отдельное подтверждение публикации в форме отзыва.'},
        {'title': 'Ваш выбор и обращения', 'text': 'Вы можете выключить аналитику и рекомендации в профиле. Для отзыва обработки данных аккаунта, исправления или удаления данных направьте обращение владельцу по указанному email. Закон предусматривает прекращение обработки в течение пятнадцати рабочих дней либо мотивированный отказ, если хранение или обработка обязательны. Неисполненные обязательства и требования закона могут ограничивать отзыв; ненужную обработку следует прекратить.'},
    ]
    analytics = {
        'title': 'Добровольная аналитика поведения и рекомендации',
        'text': 'Разрешаю владельцу анализировать мои просмотры страниц и товаров, действия в каталоге, избранное и историю покупок для оценки удобства магазина и персональных рекомендаций. Возможные данные: ID аккаунта, выбранные товары, тип действия и время. Пароли, платёжные реквизиты и содержимое адреса в события не включаются. Отказ не мешает регистрации и покупкам. Согласие действует до отключения в профиле или завершения цели. Эти данные не публикуются и не передаются рекламным сервисам. Трекер и система рекомендаций в текущей версии ещё не подключены; перед их включением владелец проверит цели, срок, получателей и соответствие этой версии согласия.',
    }
    service = {'title': 'Согласие для аккаунта и заказов',
               'text': 'Разрешаю указанному владельцу обрабатывать мои данные для аккаунта, заказов, поддержки и защиты магазина в объёме, целях и сроках, описанных в этом документе. Это согласие не включает необязательную аналитику, публикацию или отдельные передачи для карты.'}
    content = {'operator': operator, 'draft': not ready, 'sections': sections, 'service': service, 'analytics': analytics}
    version = TEMPLATE_VERSION + '.' + hashlib.sha256(json.dumps(content, ensure_ascii=False, sort_keys=True).encode()).hexdigest()[:16]
    return {**content, 'version': version, 'registration_allowed': settings.environment != 'production' or ready,
            'analytics_collection_active': False,
            'notice': 'Тестовый документ. Реквизиты и условия требуют проверки владельцем перед реальным запуском.' if not ready else 'Документ утверждён владельцем; техническая настройка не заменяет проверку фактической обработки.'}


def require_current_document(settings: Settings, version: str) -> dict:
    config = document_config(settings)
    if not config['registration_allowed']:
        raise HTTPException(503, 'Владелец ещё не подготовил документы по персональным данным для реального запуска')
    if version != config['version']:
        raise HTTPException(409, 'Условия обновились. Откройте актуальный документ и подтвердите свой выбор ещё раз')
    return config
